using Astrea.GameElements;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SharkRushAction", menuName = "Data/Battle/Battle Actions/Cellarius/Shark Rush Action")]
public class SharkRushAction : CorruptedLightningAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private DiceSecondActionLogic_AllEnemies diceSecondActionLogic_AllEnemies;

	private DiceInstance diceInstance;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance is DiceInstance)
		{
			diceInstance = ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance as DiceInstance;
		}
		CastTargetAmountWithCorruptionPurifyModifierEnum(target, amount, source, CorruptionPurifyModifierEnum.CANTBEINCREASEDCORRUPTION);
	}

	public override void SingleTargetCastAfterFirstCorruption(GameObject source)
	{
		if (diceInstance != null)
		{
			diceSecondActionLogic_AllEnemies.OnDrop(diceInstance.ActionFace, null, source);
		}
	}
}
